import React, { useEffect, useState } from "react";

import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  CartesianGrid,
} from "recharts";

const API = "http://localhost:8000";

const S = {
  page: {
    background: "#f4f7fb",
    minHeight: "100vh",
    padding: 20,
    fontFamily: "sans-serif",
  },

  header: {
    background: "white",
    padding: 20,
    borderRadius: 12,
    marginBottom: 20,
    boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
  },

  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit,minmax(220px,1fr))",
    gap: 16,
    marginBottom: 20,
  },

  card: {
    background: "white",
    borderRadius: 12,
    padding: 18,
    boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
  },

  label: {
    color: "#666",
    fontSize: 14,
    marginBottom: 8,
  },

  value: {
    fontSize: 30,
    fontWeight: 700,
  },

  alert: {
    background: "#fff0f0",
    border: "1px solid #ffb3b3",
    color: "#b00020",
    padding: 12,
    borderRadius: 10,
    marginBottom: 10,
    fontWeight: 600,
  },

  select: {
    padding: 12,
    borderRadius: 10,
    border: "1px solid #ddd",
    fontSize: 16,
    marginBottom: 20,
  },

  chatSection: {
    background: "white",
    borderRadius: 12,
    padding: 20,
    marginTop: 20,
    boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
  },

  messages: {
    height: 320,
    overflowY: "auto",
    border: "1px solid #eee",
    padding: 12,
    borderRadius: 10,
    marginBottom: 12,
    background: "#fafafa",
  },

  userMessage: {
    textAlign: "right",
    marginBottom: 12,
  },

  botMessage: {
    textAlign: "left",
    marginBottom: 12,
  },

  bubbleUser: {
    display: "inline-block",
    background: "#2563eb",
    color: "white",
    padding: 12,
    borderRadius: 12,
    maxWidth: "75%",
  },

  bubbleBot: {
    display: "inline-block",
    background: "#f1f5f9",
    color: "#111",
    padding: 12,
    borderRadius: 12,
    maxWidth: "75%",
    whiteSpace: "pre-wrap",
  },

  inputRow: {
    display: "flex",
    gap: 10,
  },

  input: {
    flex: 1,
    padding: 12,
    borderRadius: 10,
    border: "1px solid #ddd",
  },

  button: {
    background: "#2563eb",
    color: "white",
    border: "none",
    padding: "12px 20px",
    borderRadius: 10,
    cursor: "pointer",
  },
};

export default function App() {
  const [patients, setPatients] = useState([]);
  const [selected, setSelected] = useState("P0001");
  const [dashboard, setDashboard] = useState(null);

  const [query, setQuery] = useState("");
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetch(`${API}/patients`)
      .then((r) => r.json())
      .then(setPatients)
      .catch(console.error);
  }, []);

  useEffect(() => {
    fetch(`${API}/patient/${selected}`)
      .then((r) => r.json())
      .then(setDashboard)
      .catch(console.error);
  }, [selected]);

  const sendMessage = async () => {
    if (!query.trim()) return;

    const userMessage = {
      role: "user",
      text: query,
    };

    setMessages((prev) => [...prev, userMessage]);

    setLoading(true);

    try {
      const res = await fetch(`${API}/chat`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          query,
        }),
      });

      const data = await res.json();

      const botMessage = {
        role: "bot",
        text: data.answer,
      };

      setMessages((prev) => [...prev, botMessage]);
    } catch (err) {
      console.error(err);

      setMessages((prev) => [
        ...prev,
        {
          role: "bot",
          text: "Backend connection failed.",
        },
      ]);
    }

    setLoading(false);
    setQuery("");
  };

  if (!dashboard) {
    return <div style={{ padding: 20 }}>Loading dashboard...</div>;
  }

  const p = dashboard.patient;
  const s = dashboard.summary;

  return (
    <div style={S.page}>
      <div style={S.header}>
        <h1>🏥 IoT Patient Dashboard</h1>
        <p>Real-time wearable IoT healthcare monitoring system</p>
      </div>

      <select
        style={S.select}
        value={selected}
        onChange={(e) => setSelected(e.target.value)}
      >
        {patients.map((p) => (
          <option key={p.patient_id} value={p.patient_id}>
            {p.patient_id} - {p.name}
          </option>
        ))}
      </select>

      {s.alerts.map((a, i) => (
        <div key={i} style={S.alert}>
          🚨 {a}
        </div>
      ))}

      <div style={S.grid}>
        <div style={S.card}>
          <div style={S.label}>Patient</div>
          <div style={{ fontSize: 22, fontWeight: 700 }}>
            {p.name}
          </div>
          <div>{p.patient_id}</div>
          <div>{p.age} years</div>
          <div>{p.known_condition}</div>
        </div>

        <div style={S.card}>
          <div style={S.label}>Heart Rate</div>
          <div style={S.value}>
            {s.heart_rate.bpm}
          </div>
          <div>BPM</div>
        </div>

        <div style={S.card}>
          <div style={S.label}>Blood Oxygen</div>
          <div style={S.value}>
            {s.spo2.spo2_pct}%
          </div>
          <div>SpO2</div>
        </div>

        <div style={S.card}>
          <div style={S.label}>Temperature</div>
          <div style={S.value}>
            {s.temperature.temp_celsius}°C
          </div>
        </div>

        <div style={S.card}>
          <div style={S.label}>Blood Pressure</div>
          <div style={S.value}>
            {s.blood_pressure.systolic}/
            {s.blood_pressure.diastolic}
          </div>
          <div>mmHg</div>
        </div>
      </div>

      <div style={S.grid}>
        <div style={S.card}>
          <h3>Heart Rate Trend</h3>

          <ResponsiveContainer width="100%" height={250}>
            <LineChart data={dashboard.charts.heart_rate}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="timestamp" hide />
              <YAxis />
              <Tooltip />
              <Line
                type="monotone"
                dataKey="bpm"
                stroke="#2563eb"
              />
            </LineChart>
          </ResponsiveContainer>
        </div>

        <div style={S.card}>
          <h3>SpO2 Trend</h3>

          <ResponsiveContainer width="100%" height={250}>
            <LineChart data={dashboard.charts.spo2}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="timestamp" hide />
              <YAxis />
              <Tooltip />
              <Line
                type="monotone"
                dataKey="spo2_pct"
                stroke="#16a34a"
              />
            </LineChart>
          </ResponsiveContainer>
        </div>

        <div style={S.card}>
          <h3>Temperature Trend</h3>

          <ResponsiveContainer width="100%" height={250}>
            <LineChart data={dashboard.charts.temperature}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="timestamp" hide />
              <YAxis />
              <Tooltip />
              <Line
                type="monotone"
                dataKey="temp_celsius"
                stroke="#dc2626"
              />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div style={S.chatSection}>
        <h2>🤖 AI Healthcare Chatbot</h2>

        <div style={S.messages}>
          {messages.map((m, i) => (
            <div
              key={i}
              style={
                m.role === "user"
                  ? S.userMessage
                  : S.botMessage
              }
            >
              <div
                style={
                  m.role === "user"
                    ? S.bubbleUser
                    : S.bubbleBot
                }
              >
                {m.text}
              </div>
            </div>
          ))}

          {loading && (
            <div style={S.botMessage}>
              <div style={S.bubbleBot}>
                Thinking...
              </div>
            </div>
          )}
        </div>

        <div style={S.inputRow}>
          <input
            style={S.input}
            placeholder="Ask about patient vitals..."
            value={query}
            onChange={(e) =>
              setQuery(e.target.value)
            }
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                sendMessage();
              }
            }}
          />

          <button
            style={S.button}
            onClick={sendMessage}
          >
            Send
          </button>
        </div>
      </div>
    </div>
  );
}
